package com.dmitry.myai.infinix.memory; import android.content.Context; public final class LocalMemoryStore {private final android.content.SharedPreferences p; public LocalMemoryStore(Context c){p=c.getSharedPreferences("myai_memory",Context.MODE_PRIVATE);} public void put(String k,String v){p.edit().putString(k,v).apply();} public String get(String k){return p.getString(k,null);}}
